<?php if(!empty($managedPage)){$heading=$managedPage['title'];$intro='';} ?>
<section class="page-hero"><div class="container"><span class="eyebrow">سراديب</span><h1><?=e($heading??$title)?></h1><?php if(!empty($intro)):?><p><?=e($intro)?></p><?php endif;?><?=!empty($managedPage)?\App\Services\ManagedPages::body($managedPage):''?><?php if(isset($q)):?><form class="search-big" action="<?=e(locale_url($locale,'search'))?>"><input name="q" value="<?=e($q)?>" placeholder="<?=e(tr('search_ph',$locale))?>"><button class="btn btn-primary"><?=e(tr('search',$locale))?></button></form><?php endif;?></div></section><section class="section"><div class="container"><div class="story-grid"><?php foreach($articles as $a):?><article class="story-card"><a class="story-image" href="<?=e(locale_url($locale,'article/'.$a['slug']))?>" <?php if($a['featured_image']):?>style="background-image:url('<?=e($a['featured_image'])?>')"<?php endif;?>></a><div class="story-body"><div class="meta"><span><?=e($a['author_name']??'')?></span></div><h3><a href="<?=e(locale_url($locale,'article/'.$a['slug']))?>"><?=e($a['title'])?></a></h3><p><?=e($a['excerpt'])?></p></div></article><?php endforeach;?><?php if(!$articles):?><div class="empty-state"><span>⌕</span><h2><?=e(tr('no_results',$locale))?></h2><p><?=e(tr('try_again',$locale))?></p></div><?php endif;?></div></div></section>
